def transform(grid):
    objs=components(grid)
    color_counts={}
    for col,cells in objs: color_counts[col]=color_counts.get(col,0)+1
    fill=next(col for col,n in color_counts.items() if n==2)
    for col,cells in objs:
        r0,r1,c0,c1=crop(cells)
        sub=[[grid[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
        internal_bar=any(all(v==col for v in row) for row in sub[1:-1])
        if internal_bar and sum(v==1 for row in sub for v in row)==4:
            return [[fill if v==1 else v for v in row] for row in sub]
